patches.new:
// Barra apilada de sentimiento pos/neu/neg — PRIMITIVA ÚNICA.
//
// Había tres copias del mismo primitivo en este archivo con parámetros
// distintos: altura 24 / 6 / 5, radio --r-sm en dos y height/2 en la tercera,
// pista var(--canvas-2) en dos y color-mix(--text-3 16%) en la tercera, ancho
// por width:'%' en una y por flexGrow en las otras, y sólo una tenía estado
// vacío. Se generaliza ésta (la más completa) y las demás la llaman.
//
// `radius` acepta un token cuando la barra es alta (a 24px un pill se lee como
// otra cosa); `onSegment` la hace interactiva sin duplicar el markup: cada
// segmento pasa a ser <button> con nombre accesible propio.
// Los colores salen de ecoSentimentColor (data.js), la fuente única del
// producto — antes el neutral estaba escrito a mano como var(--text-3), el
// token del TEXTO secundario.
function SentimentSplitBar({ pos, neu, neg, height = 6, radius, onSegment, labelFor }) {
  const total = (pos || 0) + (neu || 0) + (neg || 0);
  const r = radius != null ? radius : height / 2;
  if (total <= 0) {
    return <div style={{ height, borderRadius: r, background: 'var(--canvas-2)' }} />;
  }
  const segs = [
    { k: 'positivo', v: pos || 0 },
    { k: 'neutral',  v: neu || 0 },
    { k: 'negativo', v: neg || 0 },
  ];
  return (
    <div style={{ display: 'flex', height, borderRadius: r, overflow: 'hidden', background: 'var(--canvas-2)' }}>
      {segs.map((s) => {
        const bg = window.ecoSentimentColor(s.k);
        const label = labelFor ? labelFor(s.k, s.v) : undefined;
        return onSegment ? (
          <button key={s.k} onClick={() => onSegment(s.k)} aria-label={label} title={label}
            style={{ flexGrow: s.v, flexBasis: 0, minWidth: 0, background: bg, border: 'none', padding: 0, cursor: 'pointer' }} />
        ) : (
          <div key={s.k} style={{ flexGrow: s.v, flexBasis: 0, minWidth: 0, background: bg }} />
        );
      })}
    </div>
  );
}

