function DeltaBadge({ info, value, metricKey = 'volume', suffix = '%', decimals = 0 }) {
  if (!info && value != null && Number.isFinite(Number(value))) {
    const v = Number(value);
    const color = window.ecoDeltaColor(metricKey, v);
    const arrow = window.ecoDeltaArrow(v);
    return (
      <span style={{ fontSize: 'var(--fs-overline)', color, fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: 'var(--sp-05)' }}>
        {arrow} {Math.abs(v).toFixed(decimals)}{suffix}
      </span>
    );
  }
  if (!info) return null;
  const toneC = { pos: 'var(--pos)', neg: 'var(--neg)', neutral: 'var(--text-3)' }[info.tone] || 'var(--text-3)';
  if (!info.hasBaseline) {
    return <span style={{ fontSize: 'var(--fs-overline)', color: 'var(--text-3)', fontWeight: 500 }}>— sin base</span>;
  }
  if (info.direction === 'flat') {
    return <span style={{ fontSize: 'var(--fs-overline)', color: 'var(--text-3)', fontWeight: 600 }}>· {info.word}</span>;
  }
  return (
    <span style={{ fontSize: 'var(--fs-overline)', color: toneC, fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: 'var(--sp-05)' }}>
      {info.arrow} {info.value}
    </span>
  );
}

patches.new:
// `size` existe para que un hero pueda pintar un delta más grande sin volver a
// duplicar el badge: el hero del NSS tenía su propia copia a --fs-caption con
// su propio mapa tono→color y decía "sin base de comparación" donde aquí se
// dice "sin base". Un solo renderizador, un solo vocabulario.
// className="num" en los cuatro retornos: el delta es una CIFRA y tokens.css
// pide tabular siempre. Sin ella, el valor de al lado salía en --ff-numeric y
// el delta en --ff-sans, con el mismo U+2212 a dos anchos distintos a tres
// caracteres de distancia.
function DeltaBadge({ info, value, metricKey = 'volume', suffix = '%', decimals = 0, size = 'var(--fs-overline)' }) {
  if (!info && value != null && Number.isFinite(Number(value))) {
    const v = Number(value);
    const color = window.ecoDeltaColor(metricKey, v);
    const arrow = window.ecoDeltaArrow(v);
    return (
      <span className="num" style={{ fontSize: size, color, fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: 'var(--sp-05)' }}>
        {arrow} {Math.abs(v).toFixed(decimals)}{suffix}
      </span>
    );
  }
  if (!info) return null;
  const toneC = { pos: 'var(--pos)', neg: 'var(--neg)', neutral: 'var(--text-3)' }[info.tone] || 'var(--text-3)';
  if (!info.hasBaseline) {
    return <span className="num" style={{ fontSize: size, color: 'var(--text-3)', fontWeight: 500 }}>— sin base</span>;
  }
  if (info.direction === 'flat') {
    return <span className="num" style={{ fontSize: size, color: 'var(--text-3)', fontWeight: 600 }}>· {info.word}</span>;
  }
  return (
    <span className="num" style={{ fontSize: size, color: toneC, fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: 'var(--sp-05)' }}>
      {info.arrow} {info.value}
    </span>
  );
}

