patches.new:
// Color de la banda en la que cae un valor. Es la ÚNICA fuente del color de un
// veredicto, y existe porque el titular y su propia banda venían de dos sitios
// distintos: el `tone` que calcula el backend (BAND_TONE en
// @eco/shared/format/metrics-display.ts) y la tabla de bandas de arriba. No
// coincidían en cuatro de los seis veredictos — ALERTA salía --neg sobre banda
// --accent, FUERTE --accent sobre banda --info, ALTA en VERDE (tone 'pos') sobre
// banda violeta y EXTREMA en ámbar sobre banda --neg. Leyendo los dos de la misma
// tabla no pueden divergir.
function bandColorAt(bands, value, max = 1) {
  if (value == null || !Number.isFinite(Number(value))) return null;
  const v = Math.min(max, Math.max(0, Number(value)));
  const b = bands.find((x, i) => v >= x.from && (v < x.to || i === bands.length - 1));
  return b ? b.color : null;
}

function crisisBand(score) {
  const s = score == null ? 0 : score;
  // El color sale de CRISIS_BANDS, no de una copia con sus propios hex: era la
  // segunda tabla de colores de crisis y ya se había desincronizado.
  const color = bandColorAt(CRISIS_BANDS, s, 1) || 'var(--verdict-0)';
