/* --seq-0 queda RESERVADO al cero real (ver seqColor en screens.js) y sube de
   0.08 a 0.14 para que una franja vacía se vea como celda y no como agujero: a
   0.08 daba 1.10:1 contra --canvas, imperceptible. --seq-1 sube de 0.24 a 0.32
   (1.43 → 1.66:1) porque es el PRIMER paso CON datos, y a 0.24 una franja con
   menciones no se distinguía de una vacía. */
--seq-0: rgba(255, 106, 61, 0.14);
--seq-1: rgba(255, 106, 61, 0.32);

/* Mismo ajuste que en oscuro: paso 0 reservado al cero real y primer paso con
   datos separable del vacío. */
--seq-0: rgba(200, 58, 30, 0.10);
--seq-1: rgba(200, 58, 30, 0.26);

